hints.text:
Una panadería apunta cada pan vendido y quiere saber qué variedades se han vendido al menos N veces.

function variedadesPopulares(ventas, n) {
  const cuentas = new Map();
  for (const pan of ventas) {
    cuentas.set(pan, (cuentas.get(pan) ?? 0) + 1);
  }
  const populares = [];
  for (const [pan, cantidad] of cuentas) {
    if (cantidad >= n) populares.push(pan);
  }
  return populares;
}
